import { createServer } from 'node:http';
import type { AddressInfo } from 'node:net';

/** Local-only auth fixture; its credential is generated by the caller, never committed. */
export async function serveAuthFixture(secret: string) {
  let origin = '';
  const server = createServer((req, res) => {
    const url = new URL(req.url ?? '/', origin);
    const html = (body: string) => {
      res.writeHead(200, { 'content-type': 'text/html' });
      res.end(`<!doctype html><html lang="en"><title>Auth fixture</title><main>${body}</main></html>`);
    };
    if (url.pathname === '/redirect') { res.writeHead(302, { location: url.searchParams.get('to') ?? '/login' }).end(); return; }
    if (url.pathname === '/robots.txt') { res.writeHead(404).end(); return; }
    if (url.pathname === '/login') {
      html('<h1>Test login</h1><form method="post" action="/session"><label>Test password <input name="password" type="password"></label><button>Log in</button></form>');
      return;
    }
    if (url.pathname === '/session' && req.method === 'POST') {
      let body = '';
      req.on('data', chunk => { body += chunk; });
      req.on('end', () => {
        if (new URLSearchParams(body).get('password') !== secret) { res.writeHead(401).end(); return; }
        res.writeHead(302, { 'set-cookie': `session=${encodeURIComponent(secret)}; Path=/; HttpOnly; SameSite=Lax`, location: '/protected' }).end();
      });
      return;
    }
    const authenticated = req.headers.cookie?.includes(`session=${encodeURIComponent(secret)}`) || req.headers.authorization === `Bearer ${secret}`;
    if (url.pathname === '/denied') { res.writeHead(403, { 'content-type': 'text/html' }).end('Denied'); return; }
    if (url.pathname === '/protected' || url.pathname === '/later') {
      if (!authenticated || url.pathname === '/later') { res.writeHead(302, { location: '/login?next=/protected' }).end(); return; }
      // Deliberately echo credentials in an accessibility violation and a passing node:
      // both the public report and native axe archive must remove them.
      html(`<h1>Protected content</h1><img src="data:," data-session="${secret}" data-encoded="${encodeURIComponent(secret)}"><p>${secret}</p><a href="/later">Expired session</a>`);
      return;
    }
    res.writeHead(404).end();
  });
  await new Promise<void>(resolve => server.listen(0, '127.0.0.1', resolve));
  origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  return { origin, close: () => new Promise<void>((resolve, reject) => server.close(error => error ? reject(error) : resolve())) };
}
